from __future__ import annotations

def coverage_report(zones: list[tuple[int, int, int, int]]) -> tuple[int, int]:
    xs = []
    ys = []
    xa = xs.append
    ya = ys.append

    for x1, y1, x2, y2 in zones:
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1
        if x1 == x2 or y1 == y2:
            continue
        xa(x1)
        xa(x2)
        ya(y1)
        ya(y2)

    if not xs:
        return (0, 0)

    xs_set = set(xs)
    ys_set = set(ys)
    transpose = len(xs_set) < len(ys_set)
    tree_coords = sorted(xs_set if transpose else ys_set)
    del xs, ys, xs_set, ys_set

    if len(tree_coords) < 2:
        return (0, 0)

    tree_id = {v: i for i, v in enumerate(tree_coords)}
    events = []
    ea = events.append

    if transpose:
        for x1, y1, x2, y2 in zones:
            if x1 > x2:
                x1, x2 = x2, x1
            if y1 > y2:
                y1, y2 = y2, y1
            if x1 == x2 or y1 == y2:
                continue
            i = tree_id[x1]
            j = tree_id[x2]
            base = i << 1
            ea((y1, base, j))
            ea((y2, base | 1, j))
    else:
        for x1, y1, x2, y2 in zones:
            if x1 > x2:
                x1, x2 = x2, x1
            if y1 > y2:
                y1, y2 = y2, y1
            if x1 == x2 or y1 == y2:
                continue
            i = tree_id[y1]
            j = tree_id[y2]
            base = i << 1
            ea((x1, base, j))
            ea((x2, base | 1, j))

    del tree_id

    if not events:
        return (0, 0)

    events.sort()

    m = len(tree_coords) - 1
    total_tree = tree_coords[-1] - tree_coords[0]

    N = 1
    while N < m:
        N <<= 1

    size = N << 1
    leaf_len = [0] * N
    for i in range(m):
        leaf_len[i] = tree_coords[i + 1] - tree_coords[i]
    del tree_coords

    cnt = [0] * size
    zero = [0] * size
    one = [0] * size

    zero[N:] = leaf_len
    for i in range(N - 1, 0, -1):
        zero[i] = zero[i << 1] + zero[(i << 1) | 1]

    height = N.bit_length()
    levels = range(1, height)

    def add(l, r, delta, cnt=cnt, zero=zero, one=one, leaf_len=leaf_len, N=N, levels=levels):
        if l >= r:
            return

        l += N
        r += N
        l0 = l
        r0 = r

        while l < r:
            if l & 1:
                c = cnt[l] + delta
                cnt[l] = c
                if l >= N:
                    L = leaf_len[l - N]
                    if c == 0:
                        zero[l] = L
                        one[l] = 0
                    elif c == 1:
                        zero[l] = 0
                        one[l] = L
                    else:
                        zero[l] = 0
                        one[l] = 0
                else:
                    lc = l << 1
                    rc = lc | 1
                    if c == 0:
                        zero[l] = zero[lc] + zero[rc]
                        one[l] = one[lc] + one[rc]
                    elif c == 1:
                        zero[l] = 0
                        one[l] = zero[lc] + zero[rc]
                    else:
                        zero[l] = 0
                        one[l] = 0
                l += 1

            if r & 1:
                r -= 1
                c = cnt[r] + delta
                cnt[r] = c
                if r >= N:
                    L = leaf_len[r - N]
                    if c == 0:
                        zero[r] = L
                        one[r] = 0
                    elif c == 1:
                        zero[r] = 0
                        one[r] = L
                    else:
                        zero[r] = 0
                        one[r] = 0
                else:
                    lc = r << 1
                    rc = lc | 1
                    if c == 0:
                        zero[r] = zero[lc] + zero[rc]
                        one[r] = one[lc] + one[rc]
                    elif c == 1:
                        zero[r] = 0
                        one[r] = zero[lc] + zero[rc]
                    else:
                        zero[r] = 0
                        one[r] = 0

            l >>= 1
            r >>= 1

        rm = r0 - 1
        for i in levels:
            p = l0 >> i
            c = cnt[p]
            lc = p << 1
            rc = lc | 1
            if c == 0:
                zero[p] = zero[lc] + zero[rc]
                one[p] = one[lc] + one[rc]
            elif c == 1:
                zero[p] = 0
                one[p] = zero[lc] + zero[rc]
            else:
                zero[p] = 0
                one[p] = 0

            q = rm >> i
            if q != p:
                c = cnt[q]
                lc = q << 1
                rc = lc | 1
                if c == 0:
                    zero[q] = zero[lc] + zero[rc]
                    one[q] = one[lc] + one[rc]
                elif c == 1:
                    zero[q] = 0
                    one[q] = zero[lc] + zero[rc]
                else:
                    zero[q] = 0
                    one[q] = 0

    covered = 0
    exclusive = 0
    prev = events[0][0]
    idx = 0
    e_len = len(events)

    while idx < e_len:
        x = events[idx][0]

        if x != prev:
            covered += (x - prev) * (total_tree - zero[1])
            exclusive += (x - prev) * one[1]
            prev = x

        while idx < e_len and events[idx][0] == x:
            e = events[idx]
            key = e[1]
            i = key >> 1
            j = e[2]
            if key & 1:
                add(i, j, -1)
            else:
                add(i, j, 1)
            idx += 1

    return covered, exclusive
